// Helper: Grade from total
function getGrade(total){
  if(total>=85) return "A";
  if(total>=80) return "A-";
  if(total>=75) return "B+";
  if(total>=70) return "B";
  if(total>=65) return "B-";
  if(total>=60) return "C+";
  if(total>=55) return "C";
  if(total>=50) return "D";
  return "F";
}

let currentStudent = null;
let filtered = [...STUDENTS];

function renderDirectory(list){
  const tbody = document.getElementById("studentTableBody");
  tbody.innerHTML = "";
  document.getElementById("countText").textContent = "Showing " + list.length + " students";
  list.forEach((s, i)=>{
    const tr = document.createElement("tr");
    tr.innerHTML = `<td>${i+1}</td><td><b>${s.name}</b><br><span style="color:#666;font-size:11px">${s.email}</span></td><td>${s.roll}</td><td>${s.department} - ${s.departmentFull}</td><td>${s.term}-${s.batch}</td><td>Sem ${s.semester} - ${s.section}</td><td><b>${s.cgpa}</b></td><td><button class="btn-small" onclick="viewStudent('${s.roll}')">View Portal</button></td>`;
    tbody.appendChild(tr);
  });
}

function applyFilters(){
  const q = document.getElementById("searchInput").value.toLowerCase();
  const dept = document.getElementById("deptFilter").value;
  const batch = document.getElementById("batchFilter").value;
  const sem = document.getElementById("semesterFilter").value;
  filtered = STUDENTS.filter(s=>{
    const matchQ = !q || s.name.toLowerCase().includes(q) || s.roll.toLowerCase().includes(q);
    const matchDept = !dept || s.department===dept;
    const matchBatch = !batch || String(s.batch)===batch;
    const matchSem = !sem || String(s.semester)===sem;
    return matchQ && matchDept && matchBatch && matchSem;
  });
  renderDirectory(filtered);
}

function viewStudent(roll){
  const s = STUDENTS.find(x=>x.roll===roll);
  if(!s) return;
  currentStudent = s;
  document.getElementById("dashboard").style.display="block";
  document.getElementById("dashboard").scrollIntoView({behavior:"smooth"});
  // Profile
  document.getElementById("dashName").textContent = s.name + " - " + s.roll;
  document.getElementById("dashMeta").textContent = s.departmentFull + " • Semester " + s.semester + " - Section " + s.section + " • Batch " + s.term + "-" + s.batch;
  const initials = s.name.split(" ").map(w=>w[0]).join("").slice(0,2).toUpperCase();
  document.getElementById("avatarText").textContent = initials;
  document.getElementById("profileName").textContent = s.name;
  document.getElementById("profileProgram").textContent = s.departmentFull;
  document.getElementById("pRoll").textContent = s.roll;
  document.getElementById("pFather").textContent = s.fatherName;
  document.getElementById("pCnic").textContent = s.cnic;
  document.getElementById("pEmail").textContent = s.email;
  document.getElementById("pPhone").textContent = s.phone;
  document.getElementById("pSection").textContent = "Sem " + s.semester + " - " + s.section;
  // Stats
  const avgAtt = (s.courses.reduce((a,c)=>a+c.attendancePct,0)/s.courses.length).toFixed(1);
  document.getElementById("statCgpa").textContent = s.cgpa;
  document.getElementById("statCgpaSub").textContent = "Semester " + s.semester;
  document.getElementById("statAtt").textContent = avgAtt + "%";
  document.getElementById("statFee").textContent = "Rs. " + s.dueFee.toLocaleString();
  document.getElementById("statFeeStatus").textContent = s.feeStatus + " • Paid Rs. " + s.paidFee.toLocaleString();
  // Courses
  const cb = document.getElementById("coursesBody");
  cb.innerHTML = s.courses.map(c=>`<tr><td>${c.code}</td><td>${c.title}</td><td>${c.teacher}</td><td>${c.credit}</td><td><b>${c.grade}</b></td></tr>`).join("");
  // Attendance
  const al = document.getElementById("attendanceList");
  al.innerHTML = s.courses.map(c=>{
    const cls = c.attendancePct < 75 ? "bar-fill low" : "bar-fill";
    return `<div class="att-row"><div class="att-top"><span>${c.code} - ${c.title}</span><span>${c.attended} / ${c.totalClasses} = ${c.attendancePct}%</span></div><div class="bar"><div class="${cls}" style="width:${c.attendancePct}%"></div></div></div>`;
  }).join("");
  // Result
  const rb = document.getElementById("resultBody");
  rb.innerHTML = s.courses.map(c=>`<tr><td>${c.code} - ${c.title}</td><td>${c.quiz}</td><td>${c.assignment}</td><td>${c.midterm}</td><td>${c.final}</td><td><b>${c.total}</b></td><td><b>${c.grade}</b></td></tr>`).join("");
  // Fee
  document.getElementById("feeTotal").textContent = "Rs. " + s.totalFee.toLocaleString();
  document.getElementById("feePaid").textContent = "Rs. " + s.paidFee.toLocaleString();
  document.getElementById("feeDue").textContent = "Rs. " + s.dueFee.toLocaleString();
  document.getElementById("feeNote").textContent = s.dueFee===0 ? "Fee is fully paid. No due amount." : "Due amount Rs. " + s.dueFee.toLocaleString() + " hai. Last date 25th of this month hai.";
  // Timetable - generate from courses
  const days = ["Monday","Tuesday","Wednesday","Thursday","Friday"];
  const tb = document.getElementById("timetableBody");
  tb.innerHTML = days.map((d, di)=>{
    const c1 = s.courses[di % s.courses.length];
    const c2 = s.courses[(di+1) % s.courses.length];
    const c3 = s.courses[(di+2) % s.courses.length];
    return `<tr><td><b>${d}</b></td><td>${c1.code} - ${c1.title}<br><small>${c1.teacher} • Room 20${di+1}</small></td><td>${c2.code} - ${c2.title}<br><small>${c2.teacher} • Room 20${di+2}</small></td><td>${c3.code} - ${c3.title}<br><small>${c3.teacher} • Lab ${di+1}</small></td></tr>`;
  }).join("");
  // Reset tabs to courses
  document.querySelectorAll(".tab-btn").forEach(b=>b.classList.remove("active"));
  document.querySelector('[data-tab="courses"]').classList.add("active");
  document.querySelectorAll(".tab-content").forEach(c=>c.classList.remove("active"));
  document.getElementById("tab-courses").classList.add("active");
}

function quickLogin(roll){
  document.getElementById("rollInput").value = roll;
  loginByRoll();
}

function loginByRoll(){
  const val = document.getElementById("rollInput").value.trim();
  const msg = document.getElementById("loginMsg");
  if(!val){ msg.textContent = "Pehle Roll Number likho."; msg.style.color="red"; return; }
  const found = STUDENTS.find(s=>s.roll.toLowerCase()===val.toLowerCase());
  if(found){
    msg.textContent = "Login kamyab! " + found.name + " ka portal khul gaya.";
    msg.style.color="green";
    viewStudent(found.roll);
  } else {
    msg.textContent = "Roll Number nahi mila. Directory me se kisi student ka Roll copy kar ke try karo. Example: " + STUDENTS[0].roll;
    msg.style.color="red";
  }
}

function randomStudent(){
  const s = STUDENTS[Math.floor(Math.random()*STUDENTS.length)];
  document.getElementById("rollInput").value = s.roll;
  loginByRoll();
}

// Events
document.getElementById("loginBtn").addEventListener("click", loginByRoll);
document.getElementById("randomBtn").addEventListener("click", randomStudent);
document.getElementById("searchInput").addEventListener("input", applyFilters);
document.getElementById("deptFilter").addEventListener("change", applyFilters);
document.getElementById("batchFilter").addEventListener("change", applyFilters);
document.getElementById("semesterFilter").addEventListener("change", applyFilters);
document.getElementById("resetBtn").addEventListener("click", ()=>{
  document.getElementById("searchInput").value="";
  document.getElementById("deptFilter").value="";
  document.getElementById("batchFilter").value="";
  document.getElementById("semesterFilter").value="";
  applyFilters();
});
document.getElementById("closeDash").addEventListener("click", ()=>{
  document.getElementById("dashboard").style.display="none";
});
document.querySelectorAll(".tab-btn").forEach(btn=>{
  btn.addEventListener("click", ()=>{
    document.querySelectorAll(".tab-btn").forEach(b=>b.classList.remove("active"));
    btn.classList.add("active");
    document.querySelectorAll(".tab-content").forEach(c=>c.classList.remove("active"));
    document.getElementById("tab-"+btn.dataset.tab).classList.add("active");
  });
});
document.getElementById("rollInput").addEventListener("keypress", (e)=>{ if(e.key==="Enter") loginByRoll(); });

// Initial render
renderDirectory(STUDENTS);
console.log("Portal loaded with", STUDENTS.length, "students");
